	\draw[dashed, line width=0.6pt, opacity=0.5] (axis cs:0,1) -- (axis cs:3,1);
	\draw[dashed, line width=0.6pt, opacity=0.5] (axis cs:0,-3) -- (axis cs:-3,-3);

